import type {HandoffScope} from './cashier-handoff';
import {sameCorrectionReview} from './invoice-correction';
export type InvoiceApplication={id:string;scope:HandoffScope;reservation:string;opening:string;invoice:string;amount:string;date:string;period:string;receivable:string;reason:string;review:Record<string,unknown>};
export const applicationUuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v);
export function validateInvoiceApplication(p:InvoiceApplication,scope:HandoffScope,reservation:string){
 if(!p||p.scope?.tenant!==scope.tenant||p.scope?.property!==scope.property||p.scope?.actor!==scope.actor||p.reservation!==reservation||![p.id,p.opening,p.invoice,p.period,p.receivable].every(applicationUuid)||typeof p.amount!=='string'||!/^[1-9][0-9]{0,11}$/.test(p.amount)||typeof p.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||typeof p.reason!=='string'||p.reason.trim()!==p.reason||p.reason.length<4||p.reason.length>500||/[\x00-\x1f\x7f]/.test(p.reason))throw Error('Invalid saved invoice application.');
 const r=p.review;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.reservation_id!==reservation||r.opening_id!==p.opening||r.invoice_id!==p.invoice||r.amount_minor!==p.amount||r.effective_on!==p.date||r.creates_external_payment!==false||r.ready_to_post!==false)throw Error('Invoice application review does not match.');
 const opening=r.opening as Record<string,unknown>,invoice=r.invoice_document as Record<string,unknown>;
 const validDate=(v:unknown):v is string=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
 const minor=(v:unknown):v is string=>typeof v==='string'&&/^(0|[1-9][0-9]{0,11})$/.test(v);
 if(!validDate(p.date)||!opening||opening.id!==p.opening||opening.tenant_id!==scope.tenant||opening.property_id!==scope.property||opening.reservation_id!==reservation||!['prepayment','security'].includes(String(opening.category))||!validDate(opening.cutover_date)||p.date<opening.cutover_date||!invoice||invoice.invoice_id!==p.invoice||invoice.tenant_id!==scope.tenant||invoice.property_id!==scope.property||invoice.actor_id!==scope.actor||invoice.reservation_id!==reservation||!validDate(invoice.issued_on)||p.date<invoice.issued_on||!minor(r.opening_available_minor)||!minor(r.invoice_available_minor)||!minor(r.invoice_outstanding_minor)||BigInt(p.amount)>BigInt(r.opening_available_minor)||BigInt(p.amount)>BigInt(r.invoice_available_minor))throw Error('Invoice application source, date or available balance is invalid.');
}
export function invoiceApplicationReceipt(v:unknown,id:string){const r=v as Record<string,unknown>;if(!r||r.request_id!==id||!applicationUuid(r.journal_id)||typeof r.replayed!=='boolean'||r.creates_external_payment!==false)throw Error('Invoice application receipt does not match.');}
export function invoiceApplicationStatus(v:unknown,p:InvoiceApplication){const r=v as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==p.scope.tenant||r.property_id!==p.scope.property||r.actor_id!==p.scope.actor||r.request_id!==p.id||typeof r.found!=='boolean'||typeof r.cancelled!=='boolean'||r.found&&r.cancelled||!r.found&&r.result!==null)throw Error('Invoice application status does not match.');if(r.found){if(!sameCorrectionReview(r.review,p.review))throw Error('Recovered invoice application review changed.');invoiceApplicationReceipt(r.result,p.id)}return r;}
